const locateMessagesWindowByExternalIDBySession = `-- name: LocateMessagesWindowByExternalIDBySession :many
WITH target AS (
  SELECT
    m.id,
    m.turn_position,
    m.turn_message_seq,
    m.created_at
  FROM bot_history_messages m
  WHERE m.team_id = public.memoh_current_team_id() AND m.session_id = $1
    AND m.turn_visible = true
    AND m.turn_id IS NOT NULL
    AND m.turn_position IS NOT NULL
    AND m.turn_message_seq IS NOT NULL
    AND m.source_message_id = $2
  ORDER BY m.turn_position DESC, m.turn_message_seq DESC, m.created_at DESC, m.id DESC
  LIMIT 1
),
before_rows AS (
  SELECT m.id
  FROM bot_history_messages m
  CROSS JOIN target
  WHERE m.team_id = public.memoh_current_team_id() AND m.session_id = $1
    AND m.turn_visible = true
    AND m.turn_id IS NOT NULL
    AND m.turn_position IS NOT NULL
    AND m.turn_message_seq IS NOT NULL
    AND (m.turn_position, m.turn_message_seq, m.created_at, m.id)
      < (target.turn_position, target.turn_message_seq, target.created_at, target.id)
  ORDER BY m.turn_position DESC, m.turn_message_seq DESC, m.created_at DESC, m.id DESC
  LIMIT $3
),
after_rows AS (
  SELECT m.id
  FROM bot_history_messages m
  CROSS JOIN target
  WHERE m.team_id = public.memoh_current_team_id() AND m.session_id = $1
    AND m.turn_visible = true
    AND m.turn_id IS NOT NULL
    AND m.turn_position IS NOT NULL
    AND m.turn_message_seq IS NOT NULL
    AND (m.turn_position, m.turn_message_seq, m.created_at, m.id)
      > (target.turn_position, target.turn_message_seq, target.created_at, target.id)
  ORDER BY m.turn_position ASC, m.turn_message_seq ASC, m.created_at ASC, m.id ASC
  LIMIT $4
),
window_rows AS (
  SELECT id FROM before_rows
  UNION ALL
  SELECT id FROM target
  UNION ALL
  SELECT id FROM after_rows
)
SELECT
  target.id AS target_id,
  target.turn_message_seq AS target_turn_message_seq,
  m.id,
  m.bot_id,
  m.session_id,
  m.sender_channel_identity_id,
  m.sender_account_user_id AS sender_user_id,
  m.source_message_id AS external_message_id,
  m.source_reply_to_message_id,
  m.role,
  m.content,
  m.metadata,
  m.turn_id,
  m.turn_position,
  m.usage,
  m.session_mode,
  m.runtime_type,
  m.event_id,
  m.display_text,
  m.created_at,
  ci.display_name AS sender_display_name,
  ci.avatar_url AS sender_avatar_url,
  s.channel_type AS platform
FROM window_rows w
CROSS JOIN target
JOIN bot_history_messages m ON m.id = w.id
LEFT JOIN channel_identities ci ON ci.id = m.sender_channel_identity_id AND ci.team_id = public.memoh_current_team_id()
LEFT JOIN bot_sessions s ON s.id = m.session_id AND s.team_id = public.memoh_current_team_id()
WHERE m.team_id = public.memoh_current_team_id() AND m.session_id = $1
  AND m.turn_visible = true
ORDER BY m.turn_position ASC, m.turn_message_seq ASC, m.created_at ASC, m.id ASC
`

